-- SYNTHETIC mock-authority world DB (PostgreSQL). Safe to load into a dedicated schema.
BEGIN;
CREATE TABLE institutions (inst_id TEXT, name TEXT, type TEXT, city TEXT, state TEXT, pin TEXT, society_id TEXT, application_type TEXT, synthetic INTEGER);
CREATE TABLE society_registry (society_id TEXT, reg_no TEXT, name TEXT, reg_date TEXT, status TEXT, president TEXT, secretary TEXT, state TEXT, synthetic INTEGER);
CREATE TABLE land_records (survey_no TEXT, holder_inst_id TEXT, holder_society_id TEXT, owner_name TEXT, area_acres DOUBLE PRECISION, tenure TEXT, lease_from TEXT, lease_to TEXT, city TEXT, state TEXT, status TEXT, synthetic INTEGER);
CREATE TABLE building_approvals (cert_no TEXT, inst_id TEXT, authority TEXT, issued_on TEXT, valid_to TEXT, sanctioned_builtup_sqm INTEGER, status TEXT);
CREATE TABLE fire_certs (cert_no TEXT, inst_id TEXT, authority TEXT, issued_on TEXT, valid_to TEXT, status TEXT);
CREATE TABLE university_affiliations (aff_no TEXT, inst_id TEXT, university TEXT, course TEXT, approved_intake INTEGER, valid_from TEXT, valid_to TEXT, status TEXT);
CREATE TABLE faculty_registry (faculty_id TEXT, name TEXT, pan TEXT, qualification TEXT, designation TEXT, synthetic INTEGER);
CREATE TABLE faculty_employment (faculty_id TEXT, inst_id TEXT, from_date TEXT, to_date TEXT);
CREATE TABLE aicte_history (inst_id TEXT, academic_year TEXT, course TEXT, level TEXT, approved_intake INTEGER, approval_ref TEXT, status TEXT);
CREATE TABLE ca_registry (firm_no TEXT, firm_name TEXT, status TEXT);
CREATE TABLE financials (inst_id TEXT, fy TEXT, ca_firm_no TEXT, total_income INTEGER, total_expenditure INTEGER, surplus INTEGER, fd_amount INTEGER);
CREATE TABLE issuer_keys (issuer TEXT, key_id TEXT, secret_hex TEXT);
CREATE TABLE scenario_flags (source TEXT, record_key TEXT, behavior TEXT, note TEXT);
COMMIT;